useEffect(() => {
    async function redraw(){ if(!mapRef.current||!layerRef.current)return; const L=await import("leaflet"); layerRef.current.clearLayers(); const points:[number,number][]=[]; if(myPoint){L.circleMarker([myPoint.latitude,myPoint.longitude],{radius:8}).bindPopup("Εσύ").addTo(layerRef.current);points.push([myPoint.latitude,myPoint.longitude]);} visible.forEach(item=>{const label=item.display_name||item.username||"Φίλος";L.circleMarker([item.latitude,item.longitude],{radius:8}).bindPopup(`${label}<br/>${item.precision_mode==="approximate"?"Περίπου":"Ακριβής θέση"}<br/>${new Date(item.updated_at).toLocaleString()}`).addTo(layerRef.current);points.push([item.latitude,item.longitude]);}); if(points.length===1)mapRef.current.setView(points[0],14); else if(points.length>1)mapRef.current.fitBounds(points,{padding:[40,40],maxZoom:14}); }
    void redraw();
  },[visible,myPoint]);

