  return (
    item.status === "approved_layer_ready" &&
    item.founderApproved === true &&
    item.derivedLayerRefs.length > 0 &&
    item.publicRawAccessAllowed === false &&
    item.githubRawStorageAllowed === false &&
    item.browserRawLoadingAllowed === false
  );
}

